export const ITERATIONS=600000;
const enc=new TextEncoder(),dec=new TextDecoder();
export const b64=b=>{let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s)};
export const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const aad=enc.encode('SafeinCloud:1');
export async function derive(password,salt){const raw=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:ITERATIONS,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
export function validate(v){if(!v||v.format!=='SafeinCloud'||v.version!==1||v.kdf!=='PBKDF2-SHA256'||v.iterations!==ITERATIONS||typeof v.salt!=='string'||typeof v.iv!=='string'||typeof v.data!=='string'||v.data.length>14000000)throw Error('Định dạng kho không được hỗ trợ.');if(bytes(v.salt).length!==16||bytes(v.iv).length!==12)throw Error('Kho bị hỏng.');return v;}
export async function seal(items,key,salt){const iv=crypto.getRandomValues(new Uint8Array(12));const data=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},key,enc.encode(JSON.stringify(items)));return{format:'SafeinCloud',version:1,kdf:'PBKDF2-SHA256',iterations:ITERATIONS,salt:b64(salt),iv:b64(iv),data:b64(new Uint8Array(data))};}
export async function open(v,password){validate(v);const salt=bytes(v.salt),key=await derive(password,salt);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(v.iv),additionalData:aad},key,bytes(v.data));const items=JSON.parse(dec.decode(plain));if(!Array.isArray(items)||items.length>20000||items.some(x=>!x||typeof x.id!=='string'||typeof x.title!=='string'||typeof x.fields!=='object'||x.fields===null))throw Error('Dữ liệu kho không hợp lệ.');return{items,key,salt};}
export function parseCSV(source){source=source.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell.length)throw Error('CSV không hợp lệ.');else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&source[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV có dấu ngoặc kép chưa đóng.');row.push(cell);if(row.some(x=>x!==''))rows.push(row);const headers=rows.shift();if(!headers||headers.join(',')!=='Title,Login,Password,URL,Notes,OTP')throw Error('Cần các cột: Title, Login, Password, URL, Notes, OTP.');return rows.map(r=>{if(r.length!==6)throw Error('Số cột CSV không đúng.');return{id:crypto.randomUUID(),title:r[0]||'Chưa đặt tên',category:'WEB',fields:Object.fromEntries(headers.slice(1).map((h,i)=>[h,r[i+1]])),updatedAt:new Date().toISOString()};});}
export function generate(length=24){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%*-_+';let result='';while(result.length<length){for(const n of crypto.getRandomValues(new Uint8Array(length*2))){if(n<256-256%chars.length)result+=chars[n%chars.length];if(result.length===length)break;}}return result;}
